import{z as n,x as i,o as l,c as C,q as r,j as t,D as B,d as e,s as o,S as s,b as a}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"风格偏置与表面特征","description":"","frontmatter":{"title":"风格偏置与表面特征","date":"2026-09-18T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/rm-style-bias.md","filePath":"llm/rm-style-bias.md","lastUpdated":1791063341000}'),d={name:"llm/rm-style-bias.md"};function F(m,E,p,D,h,b){const A=i("Mermaid");return l(),C("div",null,[E[2]||(E[2]=r('<h1 id="风格偏置与表面特征" tabindex="-1">风格偏置与表面特征 <a class="header-anchor" href="#风格偏置与表面特征" aria-label="Permalink to &quot;风格偏置与表面特征&quot;">​</a></h1><div class="epigraph"><p>内容要读懂才能评，格式扫一眼就能分；损失不知道你想要前者，它只挑成本最低的可分特征。</p><footer>—— 评测端修正见 Dubois 等 2024 的风格控制；裁判侧偏差清单见 Zheng 等 2023</footer></div><p><a href="/llm/rm-length-bias">上一课</a>把长度钉成可测量的系数 \\(\\beta\\)，本课把同一套方法推广到其余一切表面特征：列表、加粗、小标题、开场客套、自信语气、emoji。长度只是风格空间里最显眼的一维；能被 tokenizer 表面统计捕捉的特征，都是 BT 损失的廉价候选。评测端的主干已有<a href="/llm/style-control">风格控制</a>与<a href="/llm/sycophancy">谄媚</a>，本课从 RM 工程角度写：风格偏置怎么测、从哪来、怎么在不误伤真实风格价值的前提下去偏。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>风格偏置的失效模式与长度同构但更难察觉：长度有个自然标尺（token 数），风格没有。RM 偏爱列表体，策略学会把一切回答排成清单；RM 偏爱开场白「好问题！」，策略学会逢题先奉承——这与<a href="/llm/sycophancy">谄媚</a>的测量接上了：顺应的姿态在比较数据里常赢，不是因为它对。裁判侧的同款问题在 <a href="/llm/llm-judge-bias">LLM 裁判偏差</a>里列过：位置、长度、自我偏好；当裁判模型批量生产 AI 反馈时（<a href="/llm/rlaif">RLAIF</a>），偏差以工业规模写进训练池。不这么做会错在哪：所有模型的输出收敛成同一种排版，涨的是评分，丢的是「按内容回答」的能力面——评测分与用户留存开始背离。</p><p><span class="marginnote">直觉类比：风格偏置就像面试官凭西装是否笔挺打能力分——西装确实与职业度有真实相关，于是这条捷径成为最省力的判据；久之所有候选人都去买同一款西装（输出排版收敛），评分涨了，而「谁真会干活」的分辨力没了。</span></p><h3 id="测量-把风格变成可比较的量" tabindex="-1">测量：把风格变成可比较的量 <a class="header-anchor" href="#测量-把风格变成可比较的量" aria-label="Permalink to &quot;测量：把风格变成可比较的量&quot;">​</a></h3><p>长度课的三口径照搬并改写。对内差分：胜方与败方的格式特征差（列表项数、标题数、感叹号密度），报告特征与标签的频率相关——量的是数据。反事实改写：同内容两种排版（清单化 vs 散文化、加客套 vs 删客套）过 RM，看 \\(\\Delta r\\) 的分布；这是把「风格系数」推广成「风格向量」：\\(\\Delta r \\approx \\boldsymbol{\\beta}^\\top \\Delta \\boldsymbol{f}\\) ， \\(\\boldsymbol{f}\\) 是特征向量。行为端：RL 数步后输出分布的格式统计漂移，或 BoN 选中答案的格式频率变化。三口径交叉验证，缺一不可——上次的教训原样适用。</p><p><span class="marginnote">给 \\(\\Delta r \\approx \\boldsymbol{\\beta}^\\top \\Delta \\boldsymbol{f}\\) 代个数：设列表项系数 \\(\\beta_1=0.02\\)、标题系数 \\(\\beta_2=0.03\\)，一条回答比另一条多 5 个列表项、多 2 个小标题，仅凭排版 RM 就白捡 \\(5\\times0.02+2\\times0.03=0.16\\) 分——内容没变，分数已动，这就是「格式当内容用」的量化形态。</span></p>',9)),(l(),t(s,null,{default:B(()=>[o(A,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20FEAT%5B%22%E6%A0%BC%E5%BC%8F%E7%89%B9%E5%BE%81%20f%EF%BC%9A%E5%88%97%E8%A1%A8%20%2F%20%E6%A0%87%E9%A2%98%20%2F%20%E5%AE%A2%E5%A5%97%20%2F%20%E8%AF%AD%E6%B0%94%22%5D%20--%3E%20CORR%5B%22%E6%95%B0%E6%8D%AE%E5%8F%A3%E5%BE%84%EF%BC%9Af%20%E4%B8%8E%E6%A0%87%E7%AD%BE%E7%9A%84%E7%9B%B8%E5%85%B3%22%5D%0A%20%20CORR%20--%3E%20CF%5B%22%E5%8F%8D%E4%BA%8B%E5%AE%9E%E6%94%B9%E5%86%99%EF%BC%9A%CE%94r%20%E2%89%88%20%CE%B2%E1%B5%80%CE%94f%22%5D%0A%20%20CF%20--%3E%20BEH%5B%22%E8%A1%8C%E4%B8%BA%E5%8F%A3%E5%BE%84%EF%BC%9ARL%20%E5%90%8E%E6%A0%BC%E5%BC%8F%E5%88%86%E5%B8%83%E6%BC%82%E7%A7%BB%22%5D%0A%20%20BEH%20--%3E%20JUDGE%7B%22%E5%81%8F%E7%BD%AE%E8%B6%85%E6%A0%87%3F%22%7D%0A%20%20JUDGE%20--%3E%7C%E6%98%AF%7C%20FIXD%5B%22%E6%95%B0%E6%8D%AE%E7%AB%AF%EF%BC%9A%E5%8F%8D%E9%A3%8E%E6%A0%BC%E5%AF%B9%E8%BF%9B%E6%B1%A0%22%5D%0A%20%20JUDGE%20--%3E%7C%E6%98%AF%7C%20FIXC%5B%22%E8%AF%84%E6%B5%8B%E7%AB%AF%EF%BC%9A%E9%A3%8E%E6%A0%BC%E6%8E%A7%E5%88%B6%E5%9B%9E%E5%BD%92%22%5D%0A%20%20FIXD%20--%3E%20RECHECK%5B%22%E5%A4%8D%E6%B5%8B%E4%B8%89%E5%8F%A3%E5%BE%84%22%5D%0A%20%20FIXC%20--%3E%20RECHECK%0A"})]),fallback:B(()=>[...E[0]||(E[0]=[e(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=r('<h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>去偏的动作分两处。数据端：构造反事实风格对进池——同一内容，中性与浮夸两种排版，标「胜」给中性方，直接反转相关；对 AI 反馈池，先把裁判输出做格式归一（或用多个裁判交叉），降低单裁判的格式指纹。评测端：<a href="/llm/style-control">风格控制</a>的回归思路搬到内部验收——对候选回答的格式特征做回归扣除后再比较，内部评测集与外部榜统一口径。损失端通常不再额外加惩罚：风格维度太多，逐维惩罚不可维护，数据端补对是唯一可扩展的杠杆。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>风格为什么是 BT 损失的最低成本特征：RM 初始化自 SFT 模型，其表征里格式特征线性可分程度极高——不需要理解内容就能从隐层读出「这是不是列表体」。比较只要求分对，梯度先磨平格式差、再谈语义。机制上这是<a href="/llm/reward-hacking-llm">奖励黑客</a>的一般形式：任何与标签相关且比目标更易学的特征都会被优先利用。为什么数据补对仍然是最根本的解：相关结构改变后，格式特征失去预测价值，梯度不再流向它；而评测端回归只修正测量，RM 内部的格式表征原样保留，换一个不控制的下游照样复发。这条因果与长度课完全一致。</p><p><span class="marginnote">自我偏好在自评闭环里最强：模型给自己风格的回答打高分（Zheng 等 2023 观察到同族偏好），于是自奖励循环会加速格式收敛——闭环越紧，风格偏置的增长越快。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>风格不是纯噪声：排版与分节对可读性有真实贡献，用户偏好里确实含这部分。目标是切断「用格式替代内容」的混淆推理，不是惩罚一切风格——验收时用反事实对：改排版不改内容，\\(r\\) 不该大动；改内容不改排版，\\(r\\) 必须动。做不到第二条，说明去偏过度，RM 已经对内容失明。测量本身有循环：反事实改写依赖改写器，改写器的风格偏好会漏进「中性」侧；至少换两个改写器交叉验证。最后，风格空间无限，审计只能覆盖已知维度的清单——清单外的捷径靠红队与线上监控兜底，这是验收课的题。</p>',7)),(l(),t(s,null,{default:B(()=>[o(A,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20T1%5B%22%E6%B5%8B%E8%AF%95%E4%B8%80%EF%BC%9A%E6%94%B9%E6%8E%92%E7%89%88%EF%BC%8C%E4%B8%8D%E6%94%B9%E5%86%85%E5%AE%B9%22%5D%20--%3E%20R1%7B%22r%20%E5%A4%A7%E5%8A%A8%EF%BC%9F%22%7D%0A%20%20R1%20--%3E%7C%22%E6%98%AF%22%7C%20OVER%5B%22%E9%A3%8E%E6%A0%BC%E6%B7%B7%E6%B7%86%E4%BB%8D%E5%9C%A8%EF%BC%9A%E7%BB%A7%E7%BB%AD%E8%A1%A5%E5%8F%8D%E4%BA%8B%E5%AE%9E%E5%AF%B9%22%5D%0A%20%20R1%20--%3E%7C%22%E5%90%A6%22%7C%20P1%5B%22%E9%A3%8E%E6%A0%BC%E9%80%9A%E8%B7%AF%E5%B7%B2%E5%88%87%E6%96%AD%22%5D%0A%20%20T2%5B%22%E6%B5%8B%E8%AF%95%E4%BA%8C%EF%BC%9A%E6%94%B9%E5%86%85%E5%AE%B9%EF%BC%8C%E4%B8%8D%E6%94%B9%E6%8E%92%E7%89%88%22%5D%20--%3E%20R2%7B%22r%20%E5%BF%85%E9%A1%BB%E5%8A%A8%EF%BC%9F%22%7D%0A%20%20R2%20--%3E%7C%22%E5%90%A6%22%7C%20BLIND%5B%22%E5%8E%BB%E5%81%8F%E8%BF%87%E5%BA%A6%EF%BC%9ARM%20%E5%B7%B2%E5%AF%B9%E5%86%85%E5%AE%B9%E5%A4%B1%E6%98%8E%22%5D%0A%20%20R2%20--%3E%7C%22%E6%98%AF%22%7C%20P2%5B%22%E5%86%85%E5%AE%B9%E9%80%9A%E8%B7%AF%E4%BF%9D%E7%95%99%EF%BC%8C%E5%8E%BB%E5%81%8F%E5%90%88%E6%A0%BC%22%5D%0A"})]),fallback:B(()=>[...E[1]||(E[1]=[e(" Loading... ",-1)])]),_:1})),E[4]||(E[4]=a("p",null,[a("span",{class:"marginnote"},"为什么改写器本身也要审计：反事实对的「中性侧」是改写器生产的，若改写器偏爱某种排版，「中性」就不中性，测出来的风格系数被污染。至少换两个改写器交叉验证——两边一致的结果才可信，这和「两个证人对不上口供就要重查」是一个道理。")],-1)),E[5]||(E[5]=a("h2",{id:"小结",tabindex:"-1"},[e("小结 "),a("a",{class:"header-anchor",href:"#小结","aria-label":'Permalink to "小结"'},"​")],-1)),E[6]||(E[6]=a("ul",null,[a("li",null,"风格偏置是长度偏置的推广：一切表面可分特征都是 BT 的廉价候选。"),a("li",null,"测量沿用三口径：特征-标签相关（数据）、反事实改写的 \\(\\Delta r\\)（模型）、RL 后格式漂移（行为）。"),a("li",null,"去偏主杠杆在数据端反事实对，评测端用风格控制统一口径，损失端逐维惩罚不可维护。"),a("li",null,"保留真实风格价值：验收标准是「改内容必须动分，改格式不该动分」。"),a("li",null,"出处：Dubois 等 2024；Zheng 等 2023；谄媚与裁判偏差见主干课。")],-1))])}const c=n(d,[["render",F]]);export{u as __pageData,c as default};
